package com.hljzjx.classroom.reviewdraw;
import java.util.*;
import android.content.Context;
import android.os.Handler;
import android.view.View;
import android.view.MotionEvent;
import android.widget.TextView;
import com.hailiang.common.util.AppRuntimeData;
import com.hailiang.handwrite.bean.PathInfo;
import com.hailiang.handwrite.serialize.PathInfoSerializer;
import com.hailiang.handwrite.widget.HandwriteView;
import com.hailiang.xxb.room.server.*;
import com.hailiang.xxb.room.server.entity.discussion.*;
import com.nice.room.ui.roomlive.fragment.discussion.*;
import com.nice.room.ui.roomlive.tool.*;
public final class LiveRefreshTest {
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static final class Page {DiscussionFragment f=new DiscussionFragment();Context c=new Context();View root=new View(c);HandwriteView h=new HandwriteView(c);RoomToolBarView t=new RoomToolBarView(c);TextView status=new TextView(c);
  Page(long group){f.group=group;f.resumed=true;root.add("handwrite",h);root.add("handwrite_toolbar",t);root.add("tv_countdown",status);f.root=root;ReviewDrawing.refresh(f);}
  List<FunctionToolItemInfo> items(){List<FunctionToolItemInfo> list=new ArrayList<FunctionToolItemInfo>();ReviewDrawing.append(list,t.state);return list;}
  void start(){items().get(0).click.invoke(null);}void sync(){items().get(1).click.invoke(null);}void touch(int type){ReviewDrawing.touch(t,new MotionEvent(type));}
  void close(){ReviewDrawing.detach(f);f.added=false;}
 }
 static PathInfo path(long u,long id){PathInfo p=new PathInfo();p.userMark=u;p.pathID=id;p.pointsList=new ArrayList<Object>();p.pointsList.add(new Object());return p;}
 static GroupDiscussionDetail detail(long group,PathInfo...paths){GroupDiscussionDetail d=new GroupDiscussionDetail();d.group=group;DiscussionStroke member=new DiscussionStroke();for(PathInfo p:paths)member.records.add(new PathInfoSerializer().serialize(p));d.strokes.add(member);return d;}
 static DiscussionRepository.Call lastRead(){return DiscussionRepository.reads.get(DiscussionRepository.reads.size()-1);}
 static void finish(DiscussionRepository.Call call,PathInfo...paths){call.finish(new Result.Success<GroupDiscussionDetail>(detail(call.g,paths)));Handler.tick(0);}
 static boolean has(HandwriteView h,long uid,long id){for(PathInfo p:h.paths)if(p.userMark==uid&&p.pathID==id)return true;return false;}
 static void incoming(){Page p=new Page(101);finish(lastRead(),path(8,1));int n=DiscussionRepository.reads.size(),paints=p.h.paints;Handler.tick(1999);ok(DiscussionRepository.reads.size()==n,"no rapid polling");Handler.tick(1);ok(DiscussionRepository.reads.size()==n+1,"open review polls after two seconds");ok(lastRead().history&&lastRead().g==101,"same authenticated historical endpoint and group");finish(lastRead(),path(8,1),path(9,2));ok(has(p.h,9,2)&&p.h.paints==paints+1,"peer ink displayed without closing");Handler.tick(2000);finish(lastRead(),path(9,2));ok(!has(p.h,8,1)&&has(p.h,9,2),"remote deletion reflected");paints=p.h.paints;Handler.tick(2000);finish(lastRead(),path(9,2));ok(p.h.paints==paints,"identical snapshot does not repaint");ok(DiscussionRepository.appends.isEmpty(),"viewing peer ink never uploads it");p.close();}
 static void manualAndLocal(){Page p=new Page(102);finish(lastRead(),path(8,1));int n=DiscussionRepository.reads.size();p.sync();ok(DiscussionRepository.reads.size()==n+1,"sync action also reads with no drafts");finish(lastRead(),path(8,1),path(9,2));ok(has(p.h,9,2),"manual refresh displays peers");p.start();p.touch(MotionEvent.ACTION_DOWN);p.h.paths.add(path(7,3));ReviewDrawing.capture(p.f.model,20,102,path(7,3));p.touch(MotionEvent.ACTION_UP);Handler.tick(180);int writes=DiscussionRepository.appends.size();Handler.tick(1820);ok(DiscussionRepository.appends.size()==writes+1,"own ink still uploads automatically");DiscussionRepository.appends.get(writes).finish(new Result.Failure("业务拒绝"));Handler.tick(0);finish(lastRead(),path(8,1),path(9,2),path(8,4));ok(has(p.h,7,3)&&has(p.h,8,4),"rejected local draft and peer addition both retained");ok(p.status.text.equals("业务拒绝"),"passive GET does not erase upload failure");Handler.tick(2000);finish(lastRead(),path(8,1),path(9,2),path(8,4));ok(DiscussionRepository.appends.size()==writes+1,"polling does not retry a rejected write");p.close();}
 static void inputSafety(){Page p=new Page(103);finish(lastRead(),path(8,1));p.start();p.h.scale=2.5f;p.h.tx=123;p.h.ty=-74;p.h.resetTransform=true;p.touch(MotionEvent.ACTION_DOWN);int paints=p.h.paints;Handler.tick(2000);finish(lastRead(),path(8,1),path(9,2));ok(p.h.paints==paints&&!has(p.h,9,2),"response cannot replace an active stroke");p.h.paths.add(path(7,3));ReviewDrawing.capture(p.f.model,20,103,path(7,3));p.touch(MotionEvent.ACTION_UP);Handler.tick(149);ok(p.h.paints==paints,"wait for pen-up callback to complete");Handler.tick(31);ok(has(p.h,9,2)&&has(p.h,7,3),"peer snapshot merges safely after pen up");ok(p.h.scale==2.5f&&p.h.tx==123&&p.h.ty==-74,"zoom and pan preserved");
  p.h.geometry=true;paints=p.h.paints;Handler.tick(1820);finish(lastRead(),path(8,1),path(9,2),path(8,4));ok(p.h.paints==paints,"geometry edit not interrupted");p.h.geometry=false;p.touch(MotionEvent.ACTION_DOWN);p.touch(MotionEvent.ACTION_CANCEL);Handler.tick(180);ok(has(p.h,8,4),"cancel clears gesture hold");
  final int writes=DiscussionRepository.appends.size();p.h.duringApply=new Runnable(){public void run(){ReviewDrawing.capture(p.f.model,20,103,path(7,999));}};Handler.tick(1820);finish(lastRead(),path(8,1),path(9,2),path(8,4),path(8,5));Handler.tick(2000);for(int i=writes;i<DiscussionRepository.appends.size();i++)ok(!((Map)DiscussionRepository.appends.get(i).body).toString().contains("999"),"repaint never reuploads restored records");p.h.duringApply=null;for(PathInfo q:ReviewDrawing.merge(p.f,Collections.<PathInfo>emptyList()))ok(q.pathID!=999,"restored ink callback must not enter upload queue");for(DiscussionRepository.Call c:DiscussionRepository.appends)if(((Map)c.body).get("groupDiscussionGroupId").equals(103L))c.finish(new Result.Failure("test end"));Handler.tick(0);p.close();}
 static void lifecycle(){Page p=new Page(104);finish(lastRead(),path(8,1));p.f.resumed=false;int reads=DiscussionRepository.reads.size();Handler.tick(6000);ok(DiscussionRepository.reads.size()==reads,"paused review makes no refresh requests");p.f.resumed=true;Handler.tick(2000);ok(DiscussionRepository.reads.size()==reads+1,"foreground resumes without reentering");DiscussionRepository.Call old=lastRead();p.f.group=105;ReviewDrawing.refresh(p.f);DiscussionRepository.Call current=lastRead();finish(current,path(9,105));finish(old,path(8,104));ok(has(p.h,9,105)&&!has(p.h,8,104),"old group response cannot replace new group");p.h.shown=false;reads=DiscussionRepository.reads.size();Handler.tick(4000);ok(DiscussionRepository.reads.size()==reads,"hidden view does not poll");p.h.shown=true;Handler.tick(2000);ok(DiscussionRepository.reads.size()==reads+1,"shown view resumes polling");current=lastRead();p.close();finish(current,path(8,999));reads=DiscussionRepository.reads.size();Handler.tick(10000);ok(DiscussionRepository.reads.size()==reads&&!has(p.h,8,999),"closed view neither polls nor paints late data");}
 static void slowAndBackoff(){Page p=new Page(106);finish(lastRead(),path(8,1));Handler.tick(2000);DiscussionRepository.Call slow=lastRead();int reads=DiscussionRepository.reads.size();Handler.tick(12000);ok(DiscussionRepository.reads.size()==reads,"slow GET never accumulates parallel requests");slow.finish(new Result.Failure("网络失败"));Handler.tick(0);int paints=p.h.paints;Handler.tick(2000);ok(DiscussionRepository.reads.size()==reads+1,"first failure remains bounded");lastRead().finish(new Result.Failure("网络失败"));Handler.tick(0);reads=DiscussionRepository.reads.size();Handler.tick(3999);ok(DiscussionRepository.reads.size()==reads,"failure delays future requests");Handler.tick(1);ok(DiscussionRepository.reads.size()==reads+1,"bounded backoff retries");ok(p.h.paints==paints&&has(p.h,8,1),"failure retains displayed ink");finish(lastRead(),path(8,1),path(9,2));ok(has(p.h,9,2),"refresh recovers after network failure");p.close();}
 static void twoPages(){Page a=new Page(107);finish(lastRead(),path(8,1));Page b=new Page(108);finish(lastRead(),path(9,1));int start=DiscussionRepository.reads.size();Handler.tick(2000);List<DiscussionRepository.Call> calls=new ArrayList<DiscussionRepository.Call>(DiscussionRepository.reads.subList(start,DiscussionRepository.reads.size()));ok(calls.size()==2,"each visible review refreshes independently");for(DiscussionRepository.Call c:calls)finish(c,path(c.g,2));ok(has(a.h,107,2)&&has(b.h,108,2)&&!has(a.h,108,2),"two open groups cannot mix data");a.close();b.close();}
 static void account(){Page p=new Page(109);finish(lastRead(),path(8,1));Handler.tick(2000);DiscussionRepository.Call pending=lastRead();int paints=p.h.paints,reads=DiscussionRepository.reads.size();AppRuntimeData.uid=99;finish(pending,path(9,2));Handler.tick(6000);ok(p.h.paints==paints&&DiscussionRepository.reads.size()==reads,"account change stops read and repaint");p.close();AppRuntimeData.uid=7;}
 public static void main(String[] args){incoming();manualAndLocal();inputSafety();lifecycle();slowAndBackoff();twoPages();account();System.out.println("PASS LiveRefresh: "+checks+" observable adapter assertions (API fakes, no device or backend)");}
}
